/**
 * Out-of-office: setting, reading and clearing an absence, and what it does
 * to assignments, overdue alerts and mention alerts while it applies.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { SetAbsenceInput } from "@/schemas/member";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const HOUR = 60 * 60 * 1000;
const NOW = new Date("2026-06-01T07:00:00.000Z");

function at(offsetMs: number, base: Date = new Date()): IsoTimestamp {
  return new Date(base.getTime() + offsetMs).toISOString() as IsoTimestamp;
}

function absenceInput(
  tenant: Tenant,
  overrides: Partial<SetAbsenceInput> = {},
): SetAbsenceInput {
  return {
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    delegateUserId: null,
    startsAt: at(-HOUR),
    endsAt: at(HOUR),
    note: null,
    ...overrides,
  };
}

/** Away now, with the admin standing in unless told otherwise. */
async function goAway(
  tenant: Tenant,
  overrides: Partial<SetAbsenceInput> = {},
) {
  return memberService.setAbsence(
    tenant.actors.owner,
    absenceInput(tenant, { delegateUserId: tenant.userIds.admin, ...overrides }),
  );
}

async function notificationsFor(tenant: Tenant, recipientId: UserId, kind: string) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind as "issue_assigned"],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("member absence: set, get and clear", () => {
  it("stores exactly what was given and reads it back", async () => {
    const tenant = await createTenant("abs-roundtrip");
    const input = absenceInput(tenant, {
      delegateUserId: tenant.userIds.admin,
      note: "Back on Monday",
    });

    const stored = await memberService.setAbsence(tenant.actors.member, input);

    expect(stored).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: "Back on Monday",
    });
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(stored);
  });

  it("replaces an earlier absence and can clear it", async () => {
    const tenant = await createTenant("abs-replace");
    await goAway(tenant, { note: "first" });
    const second = await goAway(tenant, { delegateUserId: null, note: "second" });

    expect(second.delegateUserId).toBeNull();
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toMatchObject({ note: "second", delegateUserId: null });

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();

    // Clearing when nothing is set is fine.
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeUndefined();
  });

  it("returns a scheduled absence, and null once it has ended", async () => {
    const tenant = await createTenant("abs-window");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(NOW);

    await goAway(tenant, { startsAt: at(2 * HOUR, NOW), endsAt: at(4 * HOUR, NOW) });
    const read = () =>
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member);

    await expect(read()).resolves.not.toBeNull();
    vi.setSystemTime(new Date(NOW.getTime() + 3 * HOUR));
    await expect(read()).resolves.not.toBeNull();
    vi.setSystemTime(new Date(NOW.getTime() + 4 * HOUR - 1));
    await expect(read()).resolves.not.toBeNull();
    vi.setSystemTime(new Date(NOW.getTime() + 4 * HOUR));
    await expect(read()).resolves.toBeNull();
  });

  it("rejects an end that is not after the start", async () => {
    const tenant = await createTenant("abs-range");
    const start = at(0);

    await expect(
      memberService.setAbsence(tenant.actors.member, absenceInput(tenant, { startsAt: start, endsAt: start })),
    ).rejects.toThrow();
    await expect(
      memberService.setAbsence(tenant.actors.member, absenceInput(tenant, { startsAt: at(HOUR), endsAt: at(-HOUR) })),
    ).rejects.toThrow();
  });

  it("rejects naming yourself as your own delegate", async () => {
    const tenant = await createTenant("abs-self-delegate");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, { delegateUserId: tenant.userIds.member }),
      ),
    ).rejects.toThrow();
  });

  it("requires the member and the delegate to be active members of the workspace", async () => {
    const tenant = await createTenant("abs-active");
    const other = await createTenant("abs-active-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceInput(tenant, { userId: other.userIds.member })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceInput(tenant, { delegateUserId: other.userIds.member })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer!.id });

    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceInput(tenant, { userId: tenant.userIds.viewer })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceInput(tenant, { delegateUserId: tenant.userIds.viewer })),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets role managers act for anyone and everyone else only for themselves", async () => {
    const tenant = await createTenant("abs-permissions");

    await expect(
      memberService.setAbsence(tenant.actors.viewer, absenceInput(tenant, { userId: tenant.userIds.viewer })),
    ).resolves.toMatchObject({ userId: tenant.userIds.viewer });
    await expect(
      memberService.setAbsence(tenant.actors.admin, absenceInput(tenant)),
    ).resolves.toMatchObject({ userId: tenant.userIds.member });

    await expect(
      memberService.setAbsence(tenant.actors.member, absenceInput(tenant, { userId: tenant.userIds.viewer })),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.clearAbsence(tenant.actors.admin, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toBeUndefined();
  });

  it("rejects an org outside the actor's workspace on every operation", async () => {
    const tenant = await createTenant("abs-scope");
    const other = await createTenant("abs-scope-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceInput(other)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("drops the absence with a removed member and the delegation with a removed delegate", async () => {
    const tenant = await createTenant("abs-removal");
    await goAway(tenant, { note: "away" });
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, { userId: tenant.userIds.viewer, delegateUserId: tenant.userIds.member }),
    );

    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin!.id });

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toMatchObject({ note: "away", delegateUserId: null });

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: member!.id });

    await expect(memberRepo.findAbsence(tenant.org.id, tenant.userIds.member)).resolves.toBeNull();
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toMatchObject({ delegateUserId: null });
  });

  it("keeps workspaces independent for a user who belongs to both", async () => {
    const tenant = await createTenant("abs-indep-a");
    const other = await createTenant("abs-indep-b");
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);

    await goAway(tenant);

    await expect(
      memberService.getAbsence(other.actors.owner, other.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
    await expect(
      memberService.resolveDelegate(other.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
    await expect(
      memberService.resolveDelegate(tenant.org.id, tenant.userIds.member),
    ).resolves.toBe(tenant.userIds.admin);
  });
});

describe("member absence: assignments", () => {
  it("sends an assignment to the delegate, in the stored issue, the event and the alerts", async () => {
    const tenant = await createTenant("abs-assign");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Redirected" }),
    );
    await goAway(tenant);

    const seen: unknown[] = [];
    detachers.push(subscribe("issue.assigned", (payload) => void seen.push(payload)));

    const assigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(assigned.assigneeId).toBe(tenant.userIds.admin);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ issueId: issue.id, assigneeId: tenant.userIds.admin });
    expect(
      (await issueRepo.findIssueById(tenant.org.id, issue.id))?.assigneeId,
    ).toBe(tenant.userIds.admin);

    await expect(notificationsFor(tenant, tenant.userIds.admin, "issue_assigned")).resolves.toHaveLength(1);
    await expect(notificationsFor(tenant, tenant.userIds.member, "issue_assigned")).resolves.toHaveLength(0);
  });

  it("makes the delegate the issue's assignee for permissions", async () => {
    const tenant = await createTenant("abs-assign-perms");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Owned by delegate" }),
    );
    // The viewer can only update an issue they are the assignee of.
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, { userId: tenant.userIds.member, delegateUserId: null }).userId === tenant.userIds.member
        ? absenceInput(tenant, { userId: tenant.userIds.viewer, delegateUserId: null, startsAt: at(-2 * HOUR), endsAt: at(-HOUR) })
        : absenceInput(tenant),
    );
    await goAway(tenant, { delegateUserId: tenant.userIds.viewer });

    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    await expect(
      issueService.updateIssue(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Updated by the stand-in",
      }),
    ).resolves.toMatchObject({ title: "Updated by the stand-in" });
  });

  it("redirects an issue created with an away assignee", async () => {
    const tenant = await createTenant("abs-create");
    await goAway(tenant);

    const created: unknown[] = [];
    detachers.push(subscribe("issue.created", (payload) => void created.push(payload)));

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
    expect(created[0]).toMatchObject({ assigneeId: tenant.userIds.admin });
  });

  it("does not redirect when the away member takes the issue themselves", async () => {
    const tenant = await createTenant("abs-self-take");
    await goAway(tenant);

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);

    const other = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Take this one" }),
    );
    const taken = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: other.id,
      assigneeId: tenant.userIds.member,
    });
    expect(taken.assigneeId).toBe(tenant.userIds.member);
  });

  it("never chains: an away delegate keeps the issue", async () => {
    const tenant = await createTenant("abs-chain");
    await goAway(tenant);
    await memberService.setAbsence(
      tenant.actors.owner,
      absenceInput(tenant, { userId: tenant.userIds.admin, delegateUserId: tenant.userIds.viewer }),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("assigns as usual without a delegate, before the start and from the end on", async () => {
    const tenant = await createTenant("abs-no-redirect");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(NOW);
    const assignTo = async () =>
      (
        await issueService.createIssue(
          tenant.actors.owner,
          issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
        )
      ).assigneeId;

    await goAway(tenant, { delegateUserId: null });
    await expect(assignTo()).resolves.toBe(tenant.userIds.member);

    await goAway(tenant, { startsAt: at(HOUR, NOW), endsAt: at(2 * HOUR, NOW) });
    await expect(assignTo()).resolves.toBe(tenant.userIds.member);

    // The start counts…
    vi.setSystemTime(new Date(NOW.getTime() + HOUR));
    await expect(assignTo()).resolves.toBe(tenant.userIds.admin);

    // …the end does not.
    vi.setSystemTime(new Date(NOW.getTime() + 2 * HOUR));
    await expect(assignTo()).resolves.toBe(tenant.userIds.member);
  });
});

describe("member absence: overdue alerts", () => {
  it("sends the alert to the delegate and leaves the sweep unchanged", async () => {
    const tenant = await createTenant("abs-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number,
    );
    await goAway(tenant, { startsAt: at(-HOUR, NOW), endsAt: at(HOUR, NOW) });

    const swept: unknown[] = [];
    detachers.push(subscribe("issue.overdue", (payload) => void swept.push(payload)));

    await runOverdueIssueJob(NOW);

    expect(swept).toHaveLength(1);
    expect(swept[0]).toMatchObject({ issueId: issue.id, assigneeId: tenant.userIds.member });
    await expect(notificationsFor(tenant, tenant.userIds.admin, "issue_overdue")).resolves.toHaveLength(1);
    await expect(notificationsFor(tenant, tenant.userIds.member, "issue_overdue")).resolves.toHaveLength(0);
  });

  it("reaches the assignee as before when not away or without a delegate", async () => {
    const tenant = await createTenant("abs-overdue-plain");
    await usageRepo.recomputeUsage(tenant.org.id);
    for (const title of ["one", "two"]) {
      const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, {
          title,
          assigneeId: tenant.userIds.member,
          dueAt: "2026-01-01T00:00:00.000Z",
        }),
        tenant.userIds.owner,
        number,
      );
    }
    await goAway(tenant, { delegateUserId: null, startsAt: at(-HOUR, NOW), endsAt: at(HOUR, NOW) });

    await runOverdueIssueJob(NOW);

    await expect(notificationsFor(tenant, tenant.userIds.member, "issue_overdue")).resolves.toHaveLength(2);
    await expect(notificationsFor(tenant, tenant.userIds.admin, "issue_overdue")).resolves.toHaveLength(0);
  });
});

describe("member absence: mentions", () => {
  async function comment(tenant: Tenant, author: UserId, body: string, issueId: string) {
    const actor = Object.values(tenant.actors).find((candidate) => candidate.userId === author)!;
    return commentService.createComment(actor, {
      orgId: tenant.org.id,
      issueId: issueId as never,
      body,
      parentId: null,
      mentionedUserIds: [],
    });
  }

  it("alerts both the mentioned member and their delegate", async () => {
    const tenant = await createTenant("abs-mention");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions" }),
    );
    await goAway(tenant);

    await comment(tenant, tenant.userIds.owner, "ping @member", issue.id);

    await expect(notificationsFor(tenant, tenant.userIds.member, "comment_mention")).resolves.toHaveLength(1);
    await expect(notificationsFor(tenant, tenant.userIds.admin, "comment_mention")).resolves.toHaveLength(1);
    await expect(notificationsFor(tenant, tenant.userIds.viewer, "comment_mention")).resolves.toHaveLength(0);
  });

  it("alerts a delegate once even when mentioned directly too", async () => {
    const tenant = await createTenant("abs-mention-once");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions" }),
    );
    await goAway(tenant);

    await comment(tenant, tenant.userIds.owner, "ping @member and @admin", issue.id);

    await expect(notificationsFor(tenant, tenant.userIds.admin, "comment_mention")).resolves.toHaveLength(1);
  });

  it("never alerts the comment's author, even as a delegate", async () => {
    const tenant = await createTenant("abs-mention-author");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions" }),
    );
    await goAway(tenant);

    await comment(tenant, tenant.userIds.admin, "ping @member", issue.id);

    await expect(notificationsFor(tenant, tenant.userIds.admin, "comment_mention")).resolves.toHaveLength(0);
    await expect(notificationsFor(tenant, tenant.userIds.member, "comment_mention")).resolves.toHaveLength(1);
  });

  it("alerts only the mentioned member once the absence is over", async () => {
    const tenant = await createTenant("abs-mention-over");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions" }),
    );
    await goAway(tenant, { startsAt: at(-2 * HOUR), endsAt: at(-HOUR) });

    await comment(tenant, tenant.userIds.owner, "ping @member", issue.id);

    await expect(notificationsFor(tenant, tenant.userIds.member, "comment_mention")).resolves.toHaveLength(1);
    await expect(notificationsFor(tenant, tenant.userIds.admin, "comment_mention")).resolves.toHaveLength(0);
  });
});

